    id: '130', slug: 'the-kid', title: 'The Kid', title_ar: 'The Kid', year: 1921,
    director: 'Charlie Chaplin', director_ar: 'Charlie Chaplin',
    cast: ['Charlie Chaplin', 'Jackie Coogan', 'Carl Miller', 'Edna Purviance', 'Albert Austin', 'Beulah Bains'],
    genres: ['comedy', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/A9NWYyn7eX0H9XIjaOvfWJ9mCGA.jpg',
