    id: '161', slug: 'flow', title: 'Flow', title_ar: 'الانسياب', year: 2024,
    director: 'Gints Zilbalodis', director_ar: 'Gints Zilbalodis',
    cast: [],
    genres: ['adventure', 'animation', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/zME0Ul0w48MKkYBnFRn40M5qgLh.jpg',
